const NUMERIC = /^(0|[1-9][0-9]*)$/;
const IDENTIFIER = /^[0-9A-Za-z-]+$/;
const DIGITS = /^[0-9]+$/;

function parse(version) {
  if (typeof version !== 'string') throw new TypeError('a version must be a string');
  let rest = version;

  const plus = rest.indexOf('+');
  if (plus !== -1) {
    const build = rest.slice(plus + 1);
    rest = rest.slice(0, plus);
    if (build === '') throw new SyntaxError('the build part is empty');
    for (const part of build.split('.')) {
      if (!IDENTIFIER.test(part)) throw new SyntaxError('a build identifier is malformed');
    }
  }

  let pre = null;
  const dash = rest.indexOf('-');
  if (dash !== -1) {
    pre = rest.slice(dash + 1);
    rest = rest.slice(0, dash);
    if (pre === '') throw new SyntaxError('the prerelease part is empty');
  }

  const core = rest.split('.');
  if (core.length !== 3) throw new SyntaxError('a version needs a major, a minor and a patch');
  for (const part of core) {
    if (!NUMERIC.test(part)) throw new SyntaxError('a version number is malformed');
  }

  let identifiers = null;
  if (pre !== null) {
    identifiers = pre.split('.');
    for (const id of identifiers) {
      if (!IDENTIFIER.test(id)) throw new SyntaxError('a prerelease identifier is malformed');
      if (DIGITS.test(id) && !NUMERIC.test(id)) {
        throw new SyntaxError('a numeric prerelease identifier has a leading zero');
      }
    }
  }

  return { core: core.map(Number), pre: identifiers };
}

export function compare(a, b) {
  const left = parse(a);
  const right = parse(b);

  for (let i = 0; i < 3; i += 1) {
    if (left.core[i] !== right.core[i]) return left.core[i] < right.core[i] ? -1 : 1;
  }

  if (left.pre === null && right.pre === null) return 0;
  if (left.pre === null) return 1;
  if (right.pre === null) return -1;

  const shared = Math.min(left.pre.length, right.pre.length);
  for (let i = 0; i < shared; i += 1) {
    const x = left.pre[i];
    const y = right.pre[i];
    const xNumeric = DIGITS.test(x);
    const yNumeric = DIGITS.test(y);
    if (xNumeric && yNumeric) {
      const nx = Number(x);
      const ny = Number(y);
      if (nx !== ny) return nx < ny ? -1 : 1;
      continue;
    }
    if (xNumeric !== yNumeric) return xNumeric ? -1 : 1;
    if (x !== y) return x < y ? -1 : 1;
  }

  if (left.pre.length === right.pre.length) return 0;
  return left.pre.length < right.pre.length ? -1 : 1;
}
